const body = $json.body || {};

const token = String(body.token || '').trim();
const newSlotId = String(body.newSlotId || '').trim();

const uuidRegex =
  /^[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[1-5][0-9a-fA-F]{3}-[89abAB][0-9a-fA-F]{3}-[0-9a-fA-F]{12}$/;

if (!uuidRegex.test(token)) {
  throw new Error('Token de gestion invalide');
}

if (!uuidRegex.test(newSlotId)) {
  throw new Error('newSlotId invalide');
}

return [{
  json: {
    token,
    newSlotId
  }
}];

const item = $json || {};

if (!item.reference) {
  return [{
    json: {
      success: false,
      rescheduled: false,
      message:
        'Replanification impossible : rendez-vous introuvable, déjà annulé, créneau identique ou nouveau créneau complet'
    }
  }];
}

return [{
  json: {
    success: true,
    rescheduled: true,
    appointment: {
      reference: item.reference,
      statut: item.statut,
      service: item.service,
      site: item.site,
      debut: item.debut,
      fin: item.fin
    },
    slot: {
      id: item.creneau_id,
      capacite: item.capacite,
      places_reservees: item.places_reservees,
      places_disponibles: item.places_disponibles
    }
  }
}];
